class Solution {
public:
    int rearrangeCharacters(string s, string target) {
        int cs[26] = {}, ct[26] = {};
        for (char c : s) cs[c - 'a']++;
        for (char c : target) ct[c - 'a']++;
        int ans = INT_MAX;
        for (int i = 0; i < 26; i++)
            if (ct[i]) ans = min(ans, cs[i] / ct[i]);
        return ans;
    }
};

