class Solution:
    def rearrangeCharacters(self, s: str, target: str) -> int:
        from collections import Counter
        cs = Counter(s)
        need = Counter(target)
        copies = 0
        while all(cs[c] >= need[c] for c in need):
            for c in need: cs[c] -= need[c]
            copies += 1
        return copies

